import React from 'react';
import { AbsoluteFill, interpolate, useCurrentFrame } from 'remotion';
import { COLORS, EASINGS } from '../../brand';
import { FONT_BODY, FONT_MONO } from '../../fonts';
import { CLAMP } from '../../lib/kit';
import { CaptionTrack, CoverImage, HookTitle, ProgressBar, SAFE, ShortBg, ToolCard, Watermark, secToFrame } from '../../lib/shorts';
import { WORDS } from './words';

// short-120: generated by the daily batch. Cover held at frame 0; closes on the cover.
export const compositionConfig = { id: 'Short120', durationInSeconds: 34.0, fps: 30, width: 1080, height: 1920 };

const B1 = secToFrame(4.4);
const B2 = secToFrame(5.8);
const B3 = secToFrame(11.2);
const B4 = secToFrame(15.0);
const B5 = secToFrame(17.9);
const B6 = secToFrame(20.9);
const B7 = secToFrame(25.9);
const CTA = secToFrame(31.6);

const FadeOut: React.FC<{ at: number; children: React.ReactNode }> = ({ at, children }) => {
  const frame = useCurrentFrame();
  const op = 1 - interpolate(frame, [at - 8, at + 2], [0, 1], { ...CLAMP, easing: EASINGS.easeIn });
  return <AbsoluteFill style={{ opacity: op }}>{children}</AbsoluteFill>;
};

const Line: React.FC<{ k: string; v: string; good?: boolean; bad?: boolean }> = ({ k, v, good, bad }) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', fontFamily: FONT_MONO, fontSize: 32 }}>
    <span style={{ color: COLORS.d400 }}>{k}</span>
    <span style={{ color: bad ? COLORS.danger : good ? COLORS.signalAlt : COLORS.d300, fontWeight: good || bad ? 700 : 400 }}>{v}</span>
  </div>
);
const Panel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ background: COLORS.d900, borderRadius: 12, padding: '24px 26px', display: 'flex', flexDirection: 'column', gap: 16 }}>{children}</div>
);

const Short120: React.FC = () => {
  const frame = useCurrentFrame();
  const ctaOp = interpolate(frame, [CTA, CTA + 12], [0, 1], { ...CLAMP, easing: EASINGS.easeOut });
  const lines = [{ text: 'NEW TERRA $1 IN' }, { text: 'OLD TERRA $2 IN', accent: true }];
  return (
    <AbsoluteFill>
      <ShortBg />
      <FadeOut at={B1}>
        <CoverImage src="projects/short-120/cover.png" out={B1 - 10} />
        <HookTitle hold onDark kicker="OPENAI PRICING" lines={lines} />
      </FadeOut>
      <FadeOut at={B2}>
        <ToolCard name="GPT-6.1 Terra" tagline="The new one." chip="$1 / $5" at={B1 - 2}None>
          <Panel>
            <Line k="input /1M" v="$1.00" good />
            <Line k="output /1M" v="$5.00" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B3}>
        <ToolCard name="GPT-5.6 Terra" tagline="The old one." chip="$2 / $12" at={B2 - 2} chipColor={COLORS.danger}>
          <Panel>
            <Line k="input /1M" v="$2.00" bad />
            <Line k="output /1M" v="$12.00" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B4}>
        <ToolCard name="Half and less" tagline="Both directions." chip="2X" at={B3 - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="input" v="$2 to $1" good />
            <Line k="output" v="$12 to $5" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B5}>
        <ToolCard name="GPT-6.1 Sol" tagline="Sits above." chip="$2 / $10" at={B4 - 2}None>
          <Panel>
            <Line k="input /1M" v="$2.00" />
            <Line k="output /1M" v="$10.00" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B6}>
        <ToolCard name="GPT-6 Luna" tagline="Sits below." chip="$0.10 / $0.50" at={B5 - 2}None>
          <Panel>
            <Line k="input /1M" v="$0.10" good />
            <Line k="output /1M" v="$0.50" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B7}>
        <ToolCard name="Terra on Batch" tagline="Half again." chip="$0.50 / $2.50" at={B6 - 2}None>
          <Panel>
            <Line k="input /1M" v="$0.50" good />
            <Line k="output /1M" v="$2.50" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={CTA}>
        <ToolCard name="Old Terra" tagline="Still calling it?" chip="2X" at={B7 - 2} chipColor={COLORS.danger}>
          <Panel>
            <Line k="old input" v="$2" bad />
            <Line k="new input" v="$1" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <AbsoluteFill style={{ opacity: ctaOp }}>
        <CoverImage src="projects/short-120/cover.png" at={CTA} />
        <HookTitle hold onDark at={CTA} kicker="OPENAI PRICING" lines={lines} />
        <div style={{ position: 'absolute', left: SAFE.side, right: SAFE.side, top: SAFE.top + 520, textAlign: 'center', fontFamily: FONT_BODY, fontWeight: 600, fontSize: 44, color: 'rgba(255,255,255,0.82)' }}>
          One dollar beats two.
        </div>
      </AbsoluteFill>
      <CaptionTrack words={WORDS} />
      <Watermark at={12} />
      <ProgressBar />
    </AbsoluteFill>
  );
};
export default Short120;
